import hashlib
import json
import os
from pathlib import Path

TARGET = "llm_inputs/4b45d899a44815ed6ad07c9ca7e5b61342d69b20c12d83f57803128423140778.json"
EXPECTED_HASH = "4b45d899a44815ed6ad07c9ca7e5b61342d69b20c12d83f57803128423140778"
SOURCE_PATHS = {
    "prior_observations": ["prior_observations"],
    "parent_dependency_results": ["hierarchy_context", "parent_dependency_results"],
}


def candidates_for(relative_path):
    p = Path(relative_path)
    seen = set()
    if p.is_absolute():
        candidates = [p]
    else:
        candidates = [Path.cwd() / p]
        for parent in Path.cwd().parents:
            candidates.append(parent / p)
        candidates += [Path("/root") / p, Path("/tmp") / p,
                       Path("/workspace") / p, Path("/mnt/data") / p]
    for candidate in candidates:
        key = str(candidate)
        if key not in seen:
            seen.add(key)
            yield candidate


def locate(relative_path):
    checked = []
    for path in candidates_for(relative_path):
        checked.append(str(path))
        try:
            if path.is_file():
                return path, checked, []
        except OSError:
            continue

    # The archive may be mounted below a working directory. Search only the
    # likely data roots for this exact basename, never file contents or scripts.
    basename = Path(relative_path).name
    roots = [Path.cwd(), Path("/root"), Path("/tmp"),
             Path("/workspace"), Path("/mnt/data")]
    errors = []
    visited = set()
    for root in roots:
        try:
            root = root.resolve()
        except OSError as exc:
            errors.append({"path": str(root), "error": str(exc)})
            continue
        if str(root) in visited or not root.is_dir():
            continue
        visited.add(str(root))
        for current, dirs, files in os.walk(root, topdown=True, followlinks=False):
            dirs[:] = [d for d in dirs if d not in {"proc", "sys", "dev", ".git", "__pycache__"}]
            if basename in files:
                found = Path(current) / basename
                checked.append(str(found))
                return found, checked, errors
    return None, checked, errors


def read_json_file(path):
    raw = path.read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    try:
        value = json.loads(raw.decode("utf-8"))
        parse_error = None
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        value = None
        parse_error = str(exc)
    return raw, digest, value, parse_error


def get_path(obj, parts):
    value = obj
    for part in parts:
        if isinstance(value, dict) and part in value:
            value = value[part]
        else:
            return False, None
    return True, value


def collect_records(label, source_obj, source_file, source_path):
    parts = SOURCE_PATHS[label]
    found, value = get_path(source_obj, parts)
    return {
        "record": label,
        "source_file": str(source_file),
        "source_path": source_path,
        "retrieved": found,
        "complete_value": value if found else None,
        "completeness_note": "Value is present in the retrieved JSON file; no independent truncation claim is made." if found else "The specified path is not present in this retrieved JSON object; this does not establish that evidence is absent elsewhere."
    }


result = {
    "requested_artifact": TARGET,
    "expected_sha256_from_name": EXPECTED_HASH,
    "search": {},
    "artifact": None,
    "source_records": [],
    "referenced_originals": [],
    "limitations": []
}

artifact_path, checked, search_errors = locate(TARGET)
result["search"] = {"paths_checked": checked, "errors": search_errors}
if artifact_path is None:
    result["limitations"].append("The exact requested artifact was not found in the checked working-directory ancestors or likely archive roots. No conclusion about other inaccessible locations is made.")
else:
    try:
        raw, digest, artifact, parse_error = read_json_file(artifact_path)
        result["artifact"] = {
            "path": str(artifact_path),
            "bytes": len(raw),
            "sha256": digest,
            "filename_hash_matches_content": digest == EXPECTED_HASH,
            "json_parse_error": parse_error,
            "parsed": artifact is not None
        }
        if digest != EXPECTED_HASH:
            result["limitations"].append("The located file's content hash does not match the hash in the requested artifact filename.")
        if artifact is None:
            result["limitations"].append("The located artifact could not be parsed as UTF-8 JSON; source paths were not extracted from it.")
        else:
            for label, parts in SOURCE_PATHS.items():
                result["source_records"].append(collect_records(label, artifact, artifact_path, "$[\"" + label + "\"]" if label == "prior_observations" else "$[\"hierarchy_context\"][\"parent_dependency_results\"]"))

            # Follow original_input references embedded in evidence metadata, if present.
            refs = artifact.get("_input_context", {}).get("evidence_refs", {}) if isinstance(artifact, dict) else {}
            if isinstance(refs, dict):
                seen_originals = set()
                for ref_id, ref in refs.items():
                    if not isinstance(ref, dict):
                        continue
                    original = ref.get("original_input")
                    source_path = ref.get("source_path")
                    if not isinstance(original, dict) or not isinstance(original.get("artifact"), str):
                        continue
                    original_name = original["artifact"]
                    if original_name in seen_originals:
                        continue
                    seen_originals.add(original_name)
                    original_path, original_checked, original_errors = locate(original_name)
                    entry = {
                        "evidence_ref": ref_id,
                        "source_path": source_path,
                        "artifact_reference": original_name,
                        "search_paths_checked": original_checked,
                        "search_errors": original_errors,
                        "retrieved": original_path is not None
                    }
                    if original_path is not None:
                        try:
                            original_raw, original_digest, original_obj, original_parse_error = read_json_file(original_path)
                            entry.update({"path": str(original_path), "bytes": len(original_raw), "sha256": original_digest, "expected_sha256": original.get("sha256"), "hash_matches_reference": original_digest == original.get("sha256"), "json_parse_error": original_parse_error})
                            if original_obj is not None and isinstance(source_path, str):
                                # Resolve the JSONPath-style object path used by these references.
                                import re
                                tokens = re.findall(r'\["([^"\\]+)"\]', source_path)
                                path_found, path_value = get_path(original_obj, tokens)
                                entry["source_record_retrieved"] = path_found
                                entry["complete_source_record"] = path_value if path_found else None
                                entry["source_record_completeness_note"] = "The referenced value is present in the retrieved original JSON." if path_found else "The referenced path is not present in this retrieved original JSON; this does not prove the record is absent elsewhere."
                            else:
                                entry["source_record_retrieved"] = False
                        except OSError as exc:
                            entry["read_error"] = str(exc)
                            entry["retrieved"] = False
                    else:
                        entry["source_record_retrieved"] = False
                    result["referenced_originals"].append(entry)
            else:
                result["limitations"].append("No _input_context.evidence_refs mapping was available in the retrieved artifact.")
    except OSError as exc:
        result["limitations"].append("The artifact path was located but could not be read: " + str(exc))

print(json.dumps(result, ensure_ascii=False, indent=2))

