import hashlib
import json
import os
import sys
from pathlib import Path

ARTIFACTS = [
    "1c236bf44fb904106357b1108ac4f919cab32beecebea18e60f00543ecf93fde.json",
    "166fecf52be6be48442762ab61f24a6e4759f0ecd39c913e8f0e21dcedc3bb19.json",
]
SOURCE_PATHS = {
    "prior_observations": ["prior_observations"],
    "parent_dependency_results": ["hierarchy_context", "parent_dependency_results"],
}
SKIP_DIRS = {"proc", "sys", "dev", "run", "\.git", "node_modules", "__pycache__"}


def roots_to_search():
    candidates = [Path.cwd(), Path("/root"), Path("/tmp"), Path("/workspace"),
                  Path("/mnt/data"), Path("/llm_inputs")]
    unique = []
    seen = set()
    for candidate in candidates:
        try:
            resolved = candidate.resolve()
            key = str(resolved)
            if key not in seen and resolved.is_dir():
                seen.add(key)
                unique.append(resolved)
        except OSError:
            pass
    return unique


def locate_files(roots, names):
    found = {name: [] for name in names}
    errors = []
    checked_roots = []
    for root in roots:
        checked_roots.append(str(root))
        # Search for exact archive basenames only; do not follow symlinked directories.
        for current, dirs, files in os.walk(root, topdown=True, followlinks=False):
            dirs[:] = [d for d in dirs if d not in SKIP_DIRS and not Path(current, d).is_symlink()]
            for name in names:
                if name in files:
                    path = Path(current, name)
                    try:
                        if path.is_file():
                            found[name].append(str(path))
                    except OSError as exc:
                        errors.append({"path": str(path), "error": str(exc)})
    return found, checked_roots, errors


def resolve_path(document, parts):
    value = document
    for part in parts:
        if not isinstance(value, dict) or part not in value:
            return False, None, "path component unavailable: " + part
        value = value[part]
    return True, value, ""


def record_summary(value):
    if isinstance(value, list):
        return {"type": "list", "item_count": len(value), "empty": len(value) == 0}
    if isinstance(value, dict):
        return {"type": "object", "key_count": len(value), "keys": list(value.keys())[:50]}
    if isinstance(value, str):
        return {"type": "string", "character_count": len(value)}
    return {"type": type(value).__name__}


def main():
    roots = roots_to_search()
    found, checked_roots, errors = locate_files(roots, ARTIFACTS)
    artifacts = []
    for name in ARTIFACTS:
        paths = []
        for path_text in found[name]:
            entry = {"path": path_text, "expected_sha256_from_name": name[:-5]}
            try:
                raw = Path(path_text).read_bytes()
                entry["sha256"] = hashlib.sha256(raw).hexdigest()
                entry["byte_count"] = len(raw)
                try:
                    document = json.loads(raw.decode("utf-8"))
                    entry["json_status"] = "parsed"
                    source_records = {}
                    for label, parts in SOURCE_PATHS.items():
                        present, value, why = resolve_path(document, parts)
                        if present:
                            source_records[label] = {
                                "source_path": "$[" + "][".join(json.dumps(p) for p in parts) + "]",
                                "retrieved": True,
                                "record": record_summary(value),
                            }
                        else:
                            source_records[label] = {
                                "source_path": "$[" + "][".join(json.dumps(p) for p in parts) + "]",
                                "retrieved": False,
                                "limitation": why,
                            }
                    entry["source_records"] = source_records
                    entry["partial_or_truncated_metadata"] = document.get("_input_context", {}).get("evidence_refs") if isinstance(document, dict) else None
                except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                    entry["json_status"] = "parse_error"
                    entry["parse_error"] = str(exc)
            except OSError as exc:
                entry["read_error"] = str(exc)
            paths.append(entry)
        artifacts.append({"requested_artifact": "llm_inputs/" + name, "matches": paths,
                          "found": bool(paths)})

    result = {
        "action": "locate exact archived inputs and resolve the requested source paths",
        "search_roots_checked": checked_roots,
        "artifacts": artifacts,
        "filesystem_errors": errors,
        "limitations": [
            "Search was limited to the listed roots and exact artifact basenames; an artifact not found there may exist elsewhere.",
            "A source path is reported retrieved only when the corresponding JSON field exists in a parsed artifact; record summaries do not establish that referenced evidence is complete.",
            "No generated experiment files were used as source records."
        ],
    }
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

