import hashlib
import json
import os
import re
import sys

TARGET = "d000ab18420567fd97be9330848c0f43727883df10c46f55a8ea51a2c6ec88bb.json"
SKIP = {"/proc", "/sys", "/dev", "/run"}


def walk_filesystem():
    matches = []
    errors = []
    roots = ["/"]
    visited_roots = []
    for root in roots:
        visited_roots.append(root)
        for current, dirs, files in os.walk(root, topdown=True, followlinks=False, onerror=lambda e: errors.append({"path": getattr(e, "filename", None), "error": str(e)})):
            dirs[:] = [d for d in dirs if os.path.join(current, d) not in SKIP]
            if TARGET in files:
                matches.append(os.path.join(current, TARGET))
    return matches, errors, visited_roots


def resolve_path(document, source_path):
    """Resolve the bracketed JSON key paths used by the supplied evidence metadata."""
    value = document
    keys = re.findall(r'\[\s*"((?:[^"\\]|\\.)*)"\s*\]', source_path)
    if not keys:
        raise ValueError("unsupported or empty source path")
    for key in keys:
        key = json.loads('"' + key + '"')
        value = value[key]
    return value


def main():
    source_paths = {
        "parent_dependency_results": '$["hierarchy_context"]["parent_dependency_results"]',
        "prior_observations": '$["prior_observations"]',
    }
    matches, errors, roots = walk_filesystem()
    output = {
        "action": "locate the exact archived original and retrieve its requested source paths",
        "requested_artifact": "llm_inputs/" + TARGET,
        "search_roots_checked": roots,
        "matches": [],
        "filesystem_errors": errors,
        "limitations": [
            "Only the exact requested basename was selected; generated experiment files were not used as source records.",
            "Completeness is reported from the archived document and its evidence metadata; a retrieved value is not described as complete when its metadata marks it partial or truncated.",
        ],
    }

    for path in matches:
        entry = {"source_path": path}
        try:
            with open(path, "rb") as f:
                raw = f.read()
            entry["artifact_identity"] = {
                "basename": os.path.basename(path),
                "size_bytes": len(raw),
                "sha256": hashlib.sha256(raw).hexdigest(),
                "filename_hash_matches_content_sha256": hashlib.sha256(raw).hexdigest() == TARGET[:-5],
            }
            document = json.loads(raw.decode("utf-8"))
            entry["artifact_parse_status"] = "parsed"
            entry["original_input"] = document
            refs = document.get("_input_context", {}).get("evidence_refs", {}) if isinstance(document, dict) else {}
            retrieved = {}
            for name, source_path in source_paths.items():
                item = {"source_path": source_path}
                try:
                    value = resolve_path(document, source_path)
                    item["retrieved"] = True
                    item["value"] = value
                except (KeyError, IndexError, TypeError, ValueError) as exc:
                    item["retrieved"] = False
                    item["error"] = str(exc)
                reference = refs.get(name) if isinstance(refs, dict) else None
                if isinstance(reference, dict):
                    item["evidence_reference_metadata"] = reference
                    item["metadata_marks_partial_or_truncated"] = bool(reference.get("partial") or reference.get("truncated"))
                else:
                    item["evidence_reference_metadata"] = None
                    item["metadata_marks_partial_or_truncated"] = None
                item["completeness"] = (
                    "not retrieved" if not item["retrieved"] else
                    "metadata marks partial/truncated" if item["metadata_marks_partial_or_truncated"] else
                    "retrieved value present; no partial/truncated flag found in matching metadata"
                )
                retrieved[name] = item
            entry["requested_source_records"] = retrieved
        except Exception as exc:
            entry["artifact_parse_status"] = "error"
            entry["error"] = str(exc)
        output["matches"].append(entry)

    output["artifact_found"] = bool(matches)
    if not matches:
        output["limitations"].append("The exact artifact was not found in the filesystem roots traversed; this does not establish that it is unavailable outside the examined filesystem view.")
    json.dump(output, sys.stdout, ensure_ascii=False, indent=2)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()

