import hashlib
import json
import os
import re
import sys

ARTIFACT = "llm_inputs/6147fbca45020f8ec48cd2a7574113ac3e6505ff222621fc5665b4f21c91070e.json"
BASENAME = os.path.basename(ARTIFACT)
EXPECTED_SHA256 = os.path.basename(ARTIFACT).removesuffix(".json")
SOURCE_PATHS = {
    "parent_dependency_results": '$["parent_dependency_results"]',
    "prior_observations": '$["prior_observations"]',
}
SKIP_DIRS = {"proc", "sys", "dev"}
KEYWORDS = re.compile(r"student|192\.168\.1\.2|password|passphrase|credential|authentication|username|login|ssh|access path|private key|token", re.I)


def emit(value):
    print(json.dumps(value, ensure_ascii=False, indent=2, default=str))


def find_exact_files():
    found = []
    errors = []

    def onerror(error):
        errors.append({"path": getattr(error, "filename", None), "error": str(error)})

    for root, dirs, files in os.walk("/", topdown=True, followlinks=False, onerror=onerror):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        if BASENAME in files:
            found.append(os.path.join(root, BASENAME))
    return found, errors


def review_strings(value, path="$", hits=None, counts=None):
    if hits is None:
        hits = []
    if counts is None:
        counts = {"nodes": 0, "strings": 0}
    counts["nodes"] += 1
    if isinstance(value, dict):
        for key, child in value.items():
            review_strings(child, path + "[" + json.dumps(str(key), ensure_ascii=False) + "]", hits, counts)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            review_strings(child, path + "[" + str(index) + "]", hits, counts)
    elif isinstance(value, str):
        counts["strings"] += 1
        if KEYWORDS.search(value):
            hits.append({"path": path, "text": value})
    return hits, counts


def completeness(value):
    markers = []
    def walk(obj, path="$", seen=None):
        if seen is None:
            seen = set()
        if isinstance(obj, dict):
            for key, child in obj.items():
                key_lower = str(key).lower()
                child_path = path + "[" + json.dumps(str(key), ensure_ascii=False) + "]"
                if key_lower in {"partial", "truncated"} and child is True:
                    markers.append({"path": child_path, "value": child})
                if key_lower in {"completeness", "complete", "is_complete"}:
                    if child is False or (isinstance(child, str) and child.lower() in {"partial", "truncated", "incomplete"}):
                        markers.append({"path": child_path, "value": child})
                walk(child, child_path, seen)
        elif isinstance(obj, list):
            for i, child in enumerate(obj):
                walk(child, path + "[" + str(i) + "]", seen)
    walk(value)
    return markers


paths, search_errors = find_exact_files()
result = {
    "requested_artifact": ARTIFACT,
    "search": {"root": "/", "exact_basename_matches": paths, "filesystem_errors": search_errors},
    "identity_verification": [],
    "source_records": {},
    "limitations": ["Only the exact requested basename is considered; generated experiment files and other archived inputs are not substitutes."],
}

verified = []
for path in paths:
    try:
        with open(path, "rb") as stream:
            raw = stream.read()
        digest = hashlib.sha256(raw).hexdigest()
        identity_ok = digest == EXPECTED_SHA256
        record = {"path": path, "sha256": digest, "expected_sha256_from_name": EXPECTED_SHA256, "identity_verified": identity_ok, "bytes": len(raw)}
        result["identity_verification"].append(record)
        if identity_ok:
            verified.append((path, raw))
    except OSError as exc:
        result["identity_verification"].append({"path": path, "error": str(exc), "identity_verified": False})

if not verified:
    result["artifact_found_and_verified"] = False
    result["limitations"].append("No exact-basename file with a matching SHA-256 was accessible in the filesystem view searched; this does not establish archive unavailability beyond that view.")
    emit(result)
    sys.exit(0)

artifact_path, raw = verified[0]
try:
    artifact = json.loads(raw.decode("utf-8"))
except (UnicodeDecodeError, json.JSONDecodeError) as exc:
    result["artifact_found_and_verified"] = True
    result["artifact_path"] = artifact_path
    result["artifact_parse_error"] = str(exc)
    emit(result)
    sys.exit(0)

result["artifact_found_and_verified"] = True
result["artifact_path"] = artifact_path
result["artifact_json_parse"] = "success"
for field, source_path in SOURCE_PATHS.items():
    present = isinstance(artifact, dict) and field in artifact
    entry = {"referenced_source_path": source_path, "field_present": present}
    if present:
        value = artifact[field]
        hits, counts = review_strings(value)
        markers = completeness(value)
        entry.update({
            "value_type": type(value).__name__,
            "recursive_review_counts": counts,
            "completeness_markers": markers,
            "completeness_established": not markers,
            "keyword_evidence": hits,
            "keyword_review_note": "Matches are evidence for manual contextual review, not an automatic determination that credentials or a usable access path exist."
        })
        if not markers:
            entry["completeness_note"] = "No explicit partial/truncated marker was found within this record; this alone does not prove that an external referenced source was fully captured."
    result["source_records"][field] = entry

result["limitations"].append("The requested source paths are interpreted as top-level fields in the verified artifact. If the artifact instead references separately stored records, those records require their own accessible source locations.")
emit(result)

