import json
import os
import re
from pathlib import Path
from urllib.parse import urlsplit, urlunsplit


KEY_RE = re.compile(r"archive|artifact|llm.?input|evidence", re.I)
SECRET_RE = re.compile(r"(token|secret|password|credential|api.?key|auth)", re.I)
CANDIDATE_NAMES = {"archive", "archives", "artifact", "artifacts", "llm_inputs", "evidence"}


def safe_value(name, value):
    if SECRET_RE.search(name):
        return "<redacted>"
    value = str(value)
    # Keep a URL's scheme, host, and path, but do not disclose userinfo or query parameters.
    if "://" in value:
        try:
            parts = urlsplit(value)
            host = parts.hostname or ""
            if parts.port:
                host += ":" + str(parts.port)
            return urlunsplit((parts.scheme, host, parts.path, "<redacted>" if parts.query else "", ""))
        except Exception:
            return "<configured URL; details redacted>"
    # Avoid printing values that look like credentials while preserving locator-like paths.
    if re.search(r"(?i)(password|token|secret|bearer|api[_-]?key)=", value):
        return "<value redacted>"
    return value


def main():
    result = {
        "purpose": "discover archive locator/configuration; no exact-basename filesystem search",
        "environment": [],
        "mounts": [],
        "candidate_directories": [],
        "errors": [],
        "coverage_note": "Only matching environment variable names, mount records, and directory entries in the listed locations are examined; absence here does not establish archive unavailability."
    }

    for name, value in sorted(os.environ.items()):
        if KEY_RE.search(name):
            result["environment"].append({"name": name, "value": safe_value(name, value)})

    try:
        with open("/proc/self/mountinfo", "r", encoding="utf-8", errors="replace") as stream:
            for line in stream:
                fields = line.rstrip("\n").split()
                if len(fields) < 6:
                    continue
                mountpoint = fields[4].replace("\\040", " ").replace("\\134", "\\")
                source = fields[-1] if "-" in fields else ""
                if KEY_RE.search(mountpoint) or KEY_RE.search(source) or mountpoint in ("/mnt", "/media", "/run"):
                    result["mounts"].append({"mountpoint": mountpoint, "filesystem_source": source})
    except OSError as exc:
        result["errors"].append({"source": "/proc/self/mountinfo", "error": str(exc)})

    roots = [Path("/"), Path("/mnt"), Path("/media"), Path("/run"), Path("/var/lib"), Path("/root")]
    seen = set()
    for root in roots:
        try:
            if not root.is_dir():
                continue
            for entry in root.iterdir():
                if entry.name.lower() in CANDIDATE_NAMES or KEY_RE.search(entry.name):
                    resolved = str(entry)
                    if resolved not in seen:
                        seen.add(resolved)
                        try:
                            is_dir = entry.is_dir()
                        except OSError:
                            is_dir = None
                        result["candidate_directories"].append({"path": resolved, "is_directory": is_dir})
        except OSError as exc:
            result["errors"].append({"source": str(root), "error": str(exc)})

    print(json.dumps(result, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()

