import importlib
import inspect
import json
import sys
import traceback

ARTIFACT = "llm_inputs/6147fbca45020f8ec48cd2a7574113ac3e6505ff222621fc5665b4f21c91070e.json"
KEYWORDS = ("archive", "retrieve", "retrieval", "fetch", "read")


def text(value):
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, ensure_ascii=False, default=repr)
    except Exception:
        return repr(value)


def main():
    result = {
        "task_supplied_metadata": {
            "artifact": ARTIFACT,
            "available_in_archive": True,
            "origin": "task-provided original_input metadata",
            "note": "Availability metadata identifies the artifact but does not itself provide a retrieval interface or prove retrieval."
        },
        "inspected_sources": [],
        "documented_interfaces": [],
        "retrieval_attempt": None,
        "record_review": None,
        "coverage_and_limitations": [
            "This action inspects the deployed framework_evidence helper's runtime documentation and public API only; it does not repeat environment, mount, or directory locator discovery.",
            "A lack of an interface in these inspected sources does not establish that the archive is globally unavailable."
        ]
    }

    try:
        helper = importlib.import_module("framework_evidence")
    except Exception as exc:
        result["inspected_sources"].append({
            "source": "Python import resolution for framework_evidence",
            "status": "unavailable_or_import_error",
            "error": repr(exc)
        })
        print(json.dumps(result, ensure_ascii=False, indent=2, default=repr))
        return

    module_file = getattr(helper, "__file__", None)
    result["inspected_sources"].append({
        "source": "deployed framework_evidence module documentation and public API",
        "module_file": module_file,
        "module_doc": inspect.getdoc(helper)
    })

    candidates = []
    for name, obj in inspect.getmembers(helper):
        if name.startswith("_") or not callable(obj):
            continue
        lowered = name.lower()
        doc = inspect.getdoc(obj) or ""
        relevance = any(word in lowered for word in KEYWORDS)
        documented = bool(doc.strip())
        if relevance or any(word in doc.lower() for word in KEYWORDS):
            try:
                signature = str(inspect.signature(obj))
                parameters = inspect.signature(obj).parameters
            except (TypeError, ValueError):
                signature = None
                parameters = {}
            record = {
                "name": name,
                "signature": signature,
                "documentation": doc,
                "documented": documented
            }
            result["documented_interfaces"].append(record)
            if "archive" in lowered and any(word in lowered for word in ("retrieve", "get", "read", "fetch")):
                candidates.append((name, obj, parameters, doc, signature))

    attempted = False
    for name, function, parameters, doc, signature in candidates:
        if not doc.strip():
            continue
        path_parameters = [
            p for p in parameters.values()
            if p.name.lower() in ("artifact", "artifact_path", "path", "name", "key", "resource")
        ]
        if not path_parameters:
            continue
        required = [
            p for p in parameters.values()
            if p.default is inspect.Parameter.empty
            and p.kind not in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)
        ]
        if any(p not in path_parameters for p in required):
            result["retrieval_attempt"] = {
                "interface": name,
                "signature": signature,
                "status": "not_called",
                "reason": "The documented callable requires additional arguments not supplied by its documented signature and the task metadata."
            }
            continue
        kwargs = {p.name: ARTIFACT for p in path_parameters if p.kind != inspect.Parameter.POSITIONAL_ONLY}
        positional = [ARTIFACT] if path_parameters and path_parameters[0].kind == inspect.Parameter.POSITIONAL_ONLY else []
        try:
            value = function(*positional, **kwargs)
            if hasattr(value, "read") and callable(value.read):
                value = value.read()
            if isinstance(value, bytes):
                decoded = value.decode("utf-8", errors="replace")
            else:
                decoded = value
            result["retrieval_attempt"] = {
                "interface": name,
                "signature": signature,
                "status": "returned",
                "artifact_argument": ARTIFACT,
                "result": decoded
            }
            parsed = decoded
            if isinstance(decoded, str):
                try:
                    parsed = json.loads(decoded)
                except (json.JSONDecodeError, TypeError):
                    parsed = None
            if isinstance(parsed, dict):
                result["record_review"] = {
                    "artifact_identity": parsed.get("artifact", parsed.get("original_input", "not explicitly present in returned object")),
                    "parent_dependency_results": parsed.get("parent_dependency_results", "not present in returned object"),
                    "prior_observations": parsed.get("prior_observations", "not present in returned object"),
                    "completeness_metadata": {
                        key: parsed.get(key)
                        for key in ("complete", "partial", "truncated", "sha256", "source_path")
                        if key in parsed
                    }
                }
            attempted = True
            break
        except Exception as exc:
            result["retrieval_attempt"] = {
                "interface": name,
                "signature": signature,
                "status": "error",
                "artifact_argument": ARTIFACT,
                "error": repr(exc),
                "traceback": traceback.format_exc()
            }
            attempted = True
            break

    if not attempted and result["retrieval_attempt"] is None:
        result["retrieval_attempt"] = {
            "status": "no_callable_documented_archive_interface_found_in_inspected_helper",
            "artifact_argument": ARTIFACT,
            "note": "No matching documented callable with an artifact/path parameter was identified in this helper's public API."
        }
    print(json.dumps(result, ensure_ascii=False, indent=2, default=repr))


if __name__ == "__main__":
    main()

