    r"(?i)(\b(?:password|passwd|secret|token|api[_-]?key|access[_-]?key|credential)\b\s*[=:]\s*)([^\s,;]+)"
)
MAX_VALUE_LENGTH = 8192


def safe_value(value):
    value = SECRET_VALUE_PATTERN.sub(r"\1[REDACTED]", value)
    value = re.sub(r"(?i)(://[^:/\s]+:)[^@/\s]+(@)", r"\1[REDACTED]\2", value)
    truncated = len(value) > MAX_VALUE_LENGTH
    return value[:MAX_VALUE_LENGTH], truncated


