import hashlib
import json
from pathlib import Path

ARTIFACT = Path("llm_inputs/848154c17fa096fc5371db756718fc7f3ba157863a5198c8738e79ac44a61e42.json")
EXPECTED_ARTIFACT_SHA256 = "848154c17fa096fc5371db756718fc7f3ba157863a5198c8738e79ac44a61e42"
REQUESTS = [
    {
        "reference": "e528adf1c6d402673deafb59b3f3609a0385f2ea6da9b29272c4a4c0d65a57aa",
        "source_path": "$[\"parent_dependency_results\"]",
        "tokens": ["parent_dependency_results"],
    },
    {
        "reference": "090505863a6d43eff704d4f00f2ac4e3b4ece4ed222a19334266e96de1987364",
        "source_path": "$[\"prior_observations\"]",
        "tokens": ["prior_observations"],
    },
]


def main():
    results = []
    try:
        raw = ARTIFACT.read_bytes()
    except OSError as exc:
        for request in REQUESTS:
            results.append({
                "reference": request["reference"],
                "source_path": request["source_path"],
                "status": "unavailable",
                "artifact_path": str(ARTIFACT),
                "error": f"Could not read the supplied exact artifact path: {type(exc).__name__}: {exc}",
            })
        print(json.dumps({"artifact_path": str(ARTIFACT), "results": results}, ensure_ascii=False))
        return

    actual_artifact_hash = hashlib.sha256(raw).hexdigest()
    artifact_hash_matches = actual_artifact_hash == EXPECTED_ARTIFACT_SHA256
    try:
        document = json.loads(raw)
        parse_error = None
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        document = None
        parse_error = f"{type(exc).__name__}: {exc}"

    for request in REQUESTS:
        base = {
            "reference": request["reference"],
            "source_path": request["source_path"],
            "artifact_path": str(ARTIFACT),
            "artifact_sha256": actual_artifact_hash,
            "expected_artifact_sha256": EXPECTED_ARTIFACT_SHA256,
            "artifact_hash_matches": artifact_hash_matches,
        }
        if parse_error is not None:
            base.update({"status": "partial", "error": f"Artifact JSON parsing failed: {parse_error}"})
        elif not isinstance(document, dict) or request["tokens"][0] not in document:
            base.update({"status": "missing_response", "error": "The specified top-level source path was not present in the parsed artifact."})
        else:
            value = document[request["tokens"][0]]
            base["returned_value"] = value
            base["status"] = "complete" if artifact_hash_matches else "partial"
            if not artifact_hash_matches:
                base["limitation"] = "The requested field was read, but the artifact SHA-256 did not match the supplied original-artifact digest; completeness is not verified."
            else:
                base["completeness_basis"] = "The exact supplied artifact digest matched and the requested source path was present."
        results.append(base)

    print(json.dumps({"artifact_path": str(ARTIFACT), "results": results}, ensure_ascii=False))


if __name__ == "__main__":
    main()
